//! Bridge between the import use case and the Slint window: texts of the Data tab and the
//! import worker thread, whose results come back through the Slint event loop.

use std::path::Path;
use std::rc::Rc;

use slint::{ComponentHandle, Model, ModelRc, SharedString, VecModel};

use crate::db::{self, DbError, Stats};
use crate::update::{self, DataPaths, Origin, UpdateReport};

mod search;
mod spot;

mod generated {
    // Generated by slint-build; not under our control, so lints cannot apply.
    #![allow(clippy::all, clippy::pedantic, clippy::restriction, unsafe_code)]
    slint::include_modules!();
}

pub use generated::{AppWindow, DataStatus};

/// Texts of the Data tab, independent of Slint so they can be tested.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DataView {
    pub database_path: String,
    pub has_run: bool,
    pub started_at: String,
    pub finished_at: String,
    pub status: String,
    pub source: String,
    pub revision: String,
    pub message: String,
    pub nodes: String,
    pub items: String,
    pub drops: String,
}

const MISSING: &str = "—";

/// Describes the database for the Data tab; `stats` is `None` when no database exists yet.
pub fn describe(database: &Path, stats: Option<&Stats>) -> DataView {
    let count = |value: Option<i64>| value.map_or_else(|| MISSING.to_owned(), |n| n.to_string());
    let run = stats.and_then(|stats| stats.last_run.as_ref());
    let or_missing = |value: Option<&str>| {
        value
            .filter(|v| !v.is_empty())
            .unwrap_or(MISSING)
            .to_owned()
    };
    DataView {
        database_path: match stats {
            Some(_) => database.display().to_string(),
            None => format!("{} (absente)", database.display()),
        },
        has_run: run.is_some(),
        started_at: or_missing(run.map(|run| update::format_utc(run.started_at)).as_deref()),
        finished_at: or_missing(
            run.and_then(|run| run.finished_at)
                .map(update::format_utc)
                .as_deref(),
        ),
        status: or_missing(run.map(|run| status_label(&run.status))),
        source: or_missing(run.map(|run| source_label(&run.source))),
        revision: or_missing(run.and_then(|run| run.source_revision.as_deref())),
        message: or_missing(run.and_then(|run| run.message.as_deref())),
        nodes: count(stats.map(|s| s.nodes)),
        items: count(stats.map(|s| s.items)),
        drops: count(stats.map(|s| s.drops)),
    }
}

fn status_label(status: &str) -> &str {
    match status {
        "success" => "Réussi",
        "failed" => "Échoué",
        "running" => "En cours ou interrompu",
        other => other,
    }
}

fn source_label(source: &str) -> &str {
    match source {
        "wiki" => "Wiki (téléchargement)",
        "wiki-cache" => "Cache local",
        other => other,
    }
}

/// Reads the statistics without creating an empty database as a side effect.
pub fn read_stats(paths: &DataPaths) -> Result<Option<Stats>, DbError> {
    if !paths.database.is_file() {
        return Ok(None);
    }
    let conn = db::open(&paths.database)?;
    db::stats(&conn).map(Some)
}

/// Log lines summarising a finished import.
pub fn report_lines(result: &Result<UpdateReport, update::UpdateError>) -> Vec<String> {
    match result {
        Ok(report) => {
            let summary = &report.summary;
            let mut lines = vec![format!(
                "Import terminé : {} nœuds, {} tables, {} objets, {} drops, {} reliques, {} avertissements.",
                summary.nodes,
                summary.tables,
                summary.items,
                summary.drops,
                summary.relics,
                summary.warnings
            )];
            lines.extend(
                report
                    .warnings
                    .iter()
                    .map(|warning| format!("Avertissement : {warning}")),
            );
            lines
        }
        Err(error) => vec![format!("Échec de l'import : {error}")],
    }
}

impl From<DataView> for DataStatus {
    fn from(view: DataView) -> Self {
        Self {
            database_path: view.database_path.into(),
            has_run: view.has_run,
            started_at: view.started_at.into(),
            finished_at: view.finished_at.into(),
            status: view.status.into(),
            source: view.source.into(),
            revision: view.revision.into(),
            message: view.message.into(),
            nodes: view.nodes.into(),
            items: view.items.into(),
            drops: view.drops.into(),
        }
    }
}

/// Opens the window and runs the Slint event loop until it closes.
pub fn run(paths: DataPaths, now: fn() -> i64) -> Result<(), slint::PlatformError> {
    let window = AppWindow::new()?;
    window.set_version(env!("CARGO_PKG_VERSION").into());
    window.set_log_lines(ModelRc::from(Rc::new(VecModel::<SharedString>::default())));
    let lines = load_status(&window, &paths);
    append_lines(&window, lines);
    let (search, lines) = search::install(&window, paths.clone());
    append_lines(&window, lines);
    let (spot, lines) = spot::install(&window, paths.clone());
    append_lines(&window, lines);
    {
        let weak = window.as_weak();
        let search = Rc::downgrade(&search);
        let spot = Rc::downgrade(&spot);
        window.on_import_finished(move || {
            let Some(window) = weak.upgrade() else {
                return;
            };
            if let Some(search) = search.upgrade() {
                let lines = search.borrow_mut().reload(&window);
                append_lines(&window, lines);
            }
            if let Some(spot) = spot.upgrade() {
                let lines = spot.borrow_mut().reload(&window);
                append_lines(&window, lines);
            }
        });
    }

    for (origin, window_callback) in [
        (
            Origin::Wiki,
            AppWindow::on_update_from_wiki as fn(&AppWindow, _),
        ),
        (
            Origin::Cache,
            AppWindow::on_reimport_from_cache as fn(&AppWindow, _),
        ),
    ] {
        let weak = window.as_weak();
        let paths = paths.clone();
        let search = Rc::downgrade(&search);
        let spot = Rc::downgrade(&spot);
        window_callback(
            &window,
            Box::new(move || {
                if let Some(window) = weak.upgrade() {
                    // The search connections must not read while the import rewrites the base.
                    if let Some(search) = search.upgrade() {
                        search.borrow_mut().close();
                    }
                    if let Some(spot) = spot.upgrade() {
                        spot.borrow_mut().close();
                    }
                    start_import(&window, paths.clone(), origin, now);
                }
            }),
        );
    }
    window.run()
}

/// Shows the database state; returns log lines for a read error.
fn load_status(window: &AppWindow, paths: &DataPaths) -> Vec<String> {
    let (stats, lines) = match read_stats(paths) {
        Ok(stats) => (stats, Vec::new()),
        Err(error) => {
            log::error!("Lecture de la base : {error}");
            (
                None,
                vec![format!("Lecture de la base impossible : {error}")],
            )
        }
    };
    window.set_data_status(describe(&paths.database, stats.as_ref()).into());
    lines
}

fn append_lines(window: &AppWindow, lines: Vec<String>) {
    let model = window.get_log_lines();
    if let Some(log) = model.as_any().downcast_ref::<VecModel<SharedString>>() {
        for line in lines {
            log.push(line.into());
        }
    }
}

fn start_import(window: &AppWindow, paths: DataPaths, origin: Origin, now: fn() -> i64) {
    window.set_busy(true);
    window.set_progress(0.0);
    append_lines(
        window,
        vec![
            match origin {
                Origin::Wiki => "Mise à jour depuis le wiki…",
                Origin::Cache => "Réimport depuis le cache…",
            }
            .to_owned(),
        ],
    );

    let weak = window.as_weak();
    let worker = std::thread::Builder::new()
        .name("import".into())
        .spawn(move || {
            let result = update::run_import(&paths, origin, &now, &mut |progress| {
                log::info!("{}", progress.message);
                let fraction = progress.fraction();
                let line = progress.message.to_owned();
                post(&weak, move |window| {
                    window.set_progress(fraction);
                    append_lines(&window, vec![line]);
                });
            });
            match &result {
                Ok(report) => report
                    .warnings
                    .iter()
                    .for_each(|warning| log::warn!("{warning}")),
                Err(error) => log::error!("Import : {error}"),
            }
            let lines = report_lines(&result);
            let succeeded = result.is_ok();
            post(&weak, move |window| {
                append_lines(&window, lines);
                let read_errors = load_status(&window, &paths);
                append_lines(&window, read_errors);
                window.set_progress(if succeeded { 1.0 } else { 0.0 });
                window.set_busy(false);
                window.invoke_import_finished();
            });
        });
    if let Err(error) = worker {
        log::error!("Lancement de l'import : {error}");
        append_lines(
            window,
            vec![format!("Impossible de lancer l'import : {error}")],
        );
        window.set_busy(false);
        window.invoke_import_finished();
    }
}

/// Runs `update` on the UI thread; a closed window only loses the update.
fn post(weak: &slint::Weak<AppWindow>, update: impl FnOnce(AppWindow) + Send + 'static) {
    if let Err(error) = weak.upgrade_in_event_loop(update) {
        log::warn!("Interface indisponible : {error}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::LastRun;

    fn stats(last_run: Option<LastRun>) -> Stats {
        Stats {
            nodes: 12,
            items: 34,
            drops: 56,
            last_run,
        }
    }

    #[test]
    fn describes_missing_database() {
        let view = describe(Path::new("base.sqlite3"), None);
        assert_eq!(view.database_path, "base.sqlite3 (absente)");
        assert!(!view.has_run);
        assert_eq!(view.nodes, MISSING);
        assert_eq!(view.status, MISSING);
    }

    #[test]
    fn describes_successful_run() {
        let run = LastRun {
            started_at: 0,
            finished_at: Some(61),
            source: "wiki-cache".into(),
            source_revision: Some("rev".into()),
            status: "success".into(),
            message: None,
        };
        let view = describe(Path::new("base.sqlite3"), Some(&stats(Some(run))));
        assert_eq!(view.database_path, "base.sqlite3");
        assert!(view.has_run);
        assert_eq!(view.started_at, "1970-01-01 00:00:00 UTC");
        assert_eq!(view.finished_at, "1970-01-01 00:01:01 UTC");
        assert_eq!(view.status, "Réussi");
        assert_eq!(view.source, "Cache local");
        assert_eq!(view.revision, "rev");
        assert_eq!(view.message, MISSING);
        assert_eq!(
            (
                view.nodes.as_str(),
                view.items.as_str(),
                view.drops.as_str()
            ),
            ("12", "34", "56")
        );
    }

    #[test]
    fn describes_failed_run_without_end() {
        let run = LastRun {
            started_at: 0,
            finished_at: None,
            source: "wiki".into(),
            source_revision: None,
            status: "failed".into(),
            message: Some("réseau".into()),
        };
        let view = describe(Path::new("b"), Some(&stats(Some(run))));
        assert_eq!(view.status, "Échoué");
        assert_eq!(view.source, "Wiki (téléchargement)");
        assert_eq!(view.finished_at, MISSING);
        assert_eq!(view.message, "réseau");
    }

    #[test]
    fn missing_database_is_not_created() -> Result<(), Box<dyn std::error::Error>> {
        let dir = tempfile::tempdir()?;
        let paths = DataPaths::new(dir.path());
        assert_eq!(read_stats(&paths)?, None);
        assert!(!paths.database.exists());
        Ok(())
    }
}
